# D-FOLD-r1 insertion texts (data only). Each entry: file · anchor (unique substring of ONE line
# of the original) · offset · expect (exact content of the line after which we insert) · text.
INS = []
def add(file, anchor, text, offset=0, expect=None, id='', table=True):
    INS.append(dict(file=file, anchor=anchor, text=text, offset=offset, expect=expect, id=id, table=table))

